solution.solution.rs:
use std::fmt;
use std::marker::PhantomData;
use std::ops::Add;

trait Unit {
    const SYMBOL: &'static str;
    const TO_BASE: f64;
}

trait LengthUnit: Unit {}
trait TimeUnit: Unit {}

macro_rules! units {
    ($($name:ident => $symbol:literal, $to_base:expr;)*) => {
        $(
            #[derive(Debug, Clone, Copy, PartialEq)]
            struct $name;
            impl Unit for $name {
                const SYMBOL: &'static str = $symbol;
                const TO_BASE: f64 = $to_base;
            }
        )*
    };
}

units! {
    Metre => "m", 1.0;
    Kilometre => "km", 1000.0;
    Mile => "mi", 1609.344;
    Foot => "ft", 0.3048;
    Second => "s", 1.0;
    Minute => "min", 60.0;
    Hour => "h", 3600.0;
}

impl LengthUnit for Metre {}
impl LengthUnit for Kilometre {}
impl LengthUnit for Mile {}
impl LengthUnit for Foot {}
impl TimeUnit for Second {}
impl TimeUnit for Minute {}
impl TimeUnit for Hour {}

#[derive(Debug, Clone, Copy)]
struct Length<U: LengthUnit> {
    value: f64,
    unit: PhantomData<U>,
}

impl<U: LengthUnit> Length<U> {
    fn new(value: f64) -> Self {
        Length { value, unit: PhantomData }
    }
    fn value(&self) -> f64 {
        self.value
    }
    fn to<V: LengthUnit>(self) -> Length<V> {
        Length::new(self.value * U::TO_BASE / V::TO_BASE)
    }
}

impl<U: LengthUnit> Add for Length<U> {
    type Output = Length<U>;
    fn add(self, other: Self) -> Self {
        Length::new(self.value + other.value)
    }
}

impl<U: LengthUnit> fmt::Display for Length<U> {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "{:.2} {}", self.value, U::SYMBOL)
    }
}

#[derive(Debug, Clone, Copy)]
struct Duration<U: TimeUnit> {
    value: f64,
    unit: PhantomData<U>,
}

impl<U: TimeUnit> Duration<U> {
    fn new(value: f64) -> Self {
        Duration { value, unit: PhantomData }
    }
    fn value(&self) -> f64 {
        self.value
    }
    fn to<V: TimeUnit>(self) -> Duration<V> {
        Duration::new(self.value * U::TO_BASE / V::TO_BASE)
    }
}

impl<U: TimeUnit> Add for Duration<U> {
    type Output = Duration<U>;
    fn add(self, other: Self) -> Self {
        Duration::new(self.value + other.value)
    }
}

impl<U: TimeUnit> fmt::Display for Duration<U> {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "{:.2} {}", self.value, U::SYMBOL)
    }
}

fn parse_length(text: &str) -> Result<Length<Metre>, String> {
    let mut parts = text.split_whitespace();
    let (Some(number), Some(symbol), None) = (parts.next(), parts.next(), parts.next()) else {
        return Err(format!("expected a number and a unit, got {text:?}"));
    };
    let value: f64 = number.parse().map_err(|_| format!("not a number: {number}"))?;
    let metres = match symbol {
        s if s == Metre::SYMBOL => value * Metre::TO_BASE,
        s if s == Kilometre::SYMBOL => value * Kilometre::TO_BASE,
        s if s == Mile::SYMBOL => value * Mile::TO_BASE,
        s if s == Foot::SYMBOL => value * Foot::TO_BASE,
        other => return Err(format!("unknown length unit: {other}")),
    };
    Ok(Length::new(metres))
}

fn speed_kmh<L: LengthUnit, T: TimeUnit>(distance: Length<L>, time: Duration<T>) -> f64 {
    distance.to::<Kilometre>().value() / time.to::<Hour>().value()
}

unitTests:
test("conversions and display", || {
    let run = Length::<Kilometre>::new(3.0);
    check_eq(run.to::<Metre>().value(), 3000.0);
    check_eq(format!("{}", run.to::<Mile>()), "1.86 mi");
    check_eq(format!("{}", Length::<Foot>::new(1000.0).to::<Metre>()), "304.80 m");
    check_eq(format!("{}", Duration::<Minute>::new(90.0).to::<Hour>()), "1.50 h");
    check_eq(format!("{}", Length::<Metre>::new(1.0) + Length::new(2.5)), "3.50 m");
    check_eq(Second::SYMBOL, "s");
});

test("parsing", || {
    check_eq(parse_length("2.5 km").unwrap().value(), 2500.0);
    check_eq(parse_length("  10   ft ").unwrap().value(), 3.048);
    check(parse_length("2.5 parsecs").unwrap_err().contains("parsecs"));
    check(parse_length("far km").unwrap_err().contains("far"));
    check(parse_length("12").is_err());
    check(parse_length("1 km extra").is_err());
});

test("speed", || {
    let d = parse_length("21.0975 km").unwrap();
    let t = Duration::<Minute>::new(60.0);
    check_near(speed_kmh(d, t), 21.0975, 1e-9);
    check_near(speed_kmh(Length::<Mile>::new(1.0), Duration::<Second>::new(240.0)), 24.14016, 1e-6);
});

